import{_ as t,c as o,o as e,a4 as r}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q3：虚拟 DOM 是什么？其工作原理及 Diff 算法概述","description":"","frontmatter":{},"headers":[],"relativePath":"react/q3.md","filePath":"react/q3.md","lastUpdated":null}'),i={name:"react/q3.md"},a=r('<h1 id="q3-虚拟-dom-是什么-其工作原理及-diff-算法概述" tabindex="-1">Q3：虚拟 DOM 是什么？其工作原理及 Diff 算法概述 <a class="header-anchor" href="#q3-虚拟-dom-是什么-其工作原理及-diff-算法概述" aria-label="Permalink to &quot;Q3：虚拟 DOM 是什么？其工作原理及 Diff 算法概述&quot;">​</a></h1><p><strong>虚拟 DOM</strong>：是真实 DOM 的一个轻量级 JavaScript 对象表示，它包含了标签名、属性、子节点等信息，形成一棵虚拟树。</p><p><strong>工作原理</strong>：</p><ol><li>用虚拟 DOM 生成真实 DOM 并挂载。</li><li>状态变化时，创建一棵新的虚拟 DOM 树。</li><li>使用 Diff 算法对两棵虚拟树进行差异比较。</li><li>找到差异后，只对不同的地方进行真实 DOM 的批量更新。</li></ol><p><strong>Diff 算法三大策略</strong>（将 O(n³) 降为 O(n)）：</p><ol><li><strong>Tree Diff</strong>：只比较同级节点，跨层级移动视为删除并新建。</li><li><strong>Component Diff</strong>：组件类型不同则直接删除原组件及子树；组件类型相同则继续递归比较。</li><li><strong>Element Diff</strong>：同一层级的子元素通过 <strong>key</strong> 属性来判断是否可复用，可实现移动、复用，避免大量删除和创建。</li></ol>',6),n=[a];function s(l,f,_,c,d,p){return e(),o("div",null,n)}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
